order = []
def vanc(k):
    if k in manual: return manual[k]
    r = refs[k]; au = [f"{a.split(',')[0]} {a.split(',')[1].strip().replace('.', '')}" if "," in a else a for a in r["authors"]]
    au = [a.title() if a.split()[0].isupper() else a for a in au]; au = ", ".join(au[:6]) + (", et al." if len(au) > 6 else "")
    t = r["title"].capitalize() if r["title"].isupper() else r["title"]; yr = 2021 if k == "bilalli2021" else r["year"]
    venue = {"dianovics_lifecycle": "Lifecycle Journal"}.get(k, r.get("venue") or "")
    return f"{au}. {t}. {venue}. {yr};{r.get('volume') or ''}{('(' + r['issue'] + ')') if r.get('issue') else ''}{(':' + r['page']) if r.get('page') else ''}. https://doi.org/{r['doi']}".replace(";:", ";").replace(". ;", ". ").replace(";. ", ". ")
def cite_sub(text):
    def rep(m):
        ks = m.group(1).split(","); nums = []
        for k in ks:
            k = k.strip()
            if k not in order: order.append(k)
            nums.append(order.index(k) + 1)
        return "[" + ", ".join(map(str, sorted(nums))) + "]"
    return re.sub(r"⟦([^⟧]+)⟧", rep, text)
