def table(df, caption, size=8):
    P(caption, bold=True, size=10, space=2); t = doc.add_table(rows=1, cols=len(df.columns)); t.style = "Table Grid"
    for i, c in enumerate(df.columns): cell = t.rows[0].cells[i]; cell.text = ""; r = cell.paragraphs[0].add_run(str(c)); r.bold = True; r.font.size = Pt(size)
    for _, row in df.iterrows():
        cells = t.add_row().cells
        for i, v in enumerate(row): cells[i].text = ""; r = cells[i].paragraphs[0].add_run(v if isinstance(v, str) else (f"{v:.3f}" if isinstance(v, float) else str(v))); r.font.size = Pt(size)
    for row in t.rows:
        for c in row.cells:
            for p in c.paragraphs: p.paragraph_format.line_spacing = 1.0; p.paragraph_format.space_after = Pt(0)
    doc.add_paragraph().paragraph_format.space_after = Pt(4)
